import {SCENARIOS,buildCaseScenario,missingInputs} from './scenarios.mjs';
import {EVIDENCE,SOURCED_PROPOSAL} from './sources.mjs';
import {DEFAULTS,PRESETS,CASES,COOLING,SOURCE,simulate} from './model.mjs';
let p=buildCaseScenario('B','optimistic'), year=2030, timer, engineData=null, engineMeta=null;
let comparisonSequence=0;
let showClassical=false;
let profileCustomized=false;
const liveEngine=document.documentElement.dataset.mode==='live';
const replayUrl=()=>liveEngine?'/router/':`./snapshots/router-replay-${p.caseId}.html`;
const $=id=>document.getElementById(id), fmt=(v,d=1)=>Number(v).toLocaleString('en-US',{maximumFractionDigits:d}),money=v=>`${v<0?'−':''}$${fmt(Math.abs(v)/(Math.abs(v)>=1e9?1e9:Math.abs(v)>=1e6?1e6:Math.abs(v)>=1e3?1e3:1),2)}${Math.abs(v)>=1e9?'B':Math.abs(v)>=1e6?'M':Math.abs(v)>=1e3?'k':''}`;
const population=n=>n>=1e9?`${fmt(n/1e9,1)}B`:`${fmt(n/1e6,0)}M`;
const groups=[
 ['QC router rollout',[
 ['qcRouterOn','Routing QPUs',{true:'Enabled · QC assignment rollout',false:'Disabled · classical policy reference'}],
 ['qcRouterStart','First QC router year',2030,2040,1,''],['qcRouterInitial','QC routers in first rollout year',0,100,1,''],['qcRouterAdd','QC routers added each later year',0,20,1,''],['qcRouterMax','Maximum QC routers',0,100,1,''],['qcRouterCoverage','2030 assignment workload per QC router',1,100,1,'%'],['qcAdoptionStart','Assignments deployed to QC in first year',0,100,1,'%'],['qcAdoptionEndYear','Year QC assignment deployment reaches 100%',2030,2040,1,''],['qcRouterGain','Extra throughput on QC-covered work (assumed)',0,50,1,'%'],
 ['caseId','User case',{A:'A · Prompters · 4B users',B:'B · Agent developers · 50M users',C:'C · Knowledge workers · 400M users'}],['specDecode','Speculative decoding',{false:'Off · brief levers only',true:'On · source assumption: 2 accepted tokens'}],['reference','Savings comparison',{unoptimizedGpu:'GPU fleet before routing improvements',optimizedGpu:'GPU fleet with optimized classical router'}],['preset','Routing scenario',Object.fromEntries(Object.entries(SCENARIOS).map(([id,s])=>[id,s.label]))],['rolloutStrategy','Recommendation goal',{bestCost:'Lowest five-year cost · candidate search',staged:'Annual deployment · 2030 through 2040'}],['gpuKeep','Capacity buffer after offloading',0,150,5,'%'],['demandGrowth','Annual work per user growth',0,25,1,'%'],['gpuGrowth','Annual GPU throughput gain',0,30,1,'%']]],
 ['Optional scientific tool QPUs',[['start','First tool-QPU purchase',2030,2040,1,''],['qAvailableFrom','Earliest feasible quantum year',2030,2040,1,''],['qAnchorYear','Quantum parameter anchor year',2030,2040,1,''],['add','Tool QPUs added each year',0,20,1,''],['maxQ','Maximum tool QPUs',0,100,1,''],
 ['toolShare','Extra scientific work / LLM GPU work',0,100,5,'%'],['eligible','Initially quantum-eligible tools',0,100,5,'%'],['eligibilityGrowth','Eligibility increase / year',0,10,1,'pp'],['qJobs','Completed jobs / Q system / hour',1,10000,10,''],['jobHours','GPU-hours per same scientific job',0.01,10000000,0.01,'h'],['qLogical','Initial logical qubits / system',1,2000,1,''],['requiredLogical','Logical qubits required per job',1,2000,1,''],['qGrowth','Annual qubit & throughput gain',0,100,5,'%'],['qMw','Initial whole Q system power',0.01,40,0.01,'MW'],['qPowerDrop','Power reduction on new systems / year',0,30,1,'%'],['qPrice','Initial price / complete Q system',1,1000,1,'$M'],['qPriceDrop','Price reduction / year',0,30,1,'%']]],
 ['QC task-assignment router',[
 ['qcRouterMw','Power per QC router',0,40,0.001,'MW'],['qcRouterPrice','Purchase price per QC router',0,1000,1,'$M'],['qcRouterLatencyMs','QC assignment decision latency',1,1000,1,'ms']]],
 ['Optional tool-pool scheduler assumptions',[
 ['router','Scheduler',{classical:'Classical baseline',quantum:'Quantum-assisted · simulated'}],['routerGain','Assumed capacity gain from scheduling',0,30,1,'%'],['routerMs','Assignment decision latency',1,1000,1,'ms'],['routerKw','Additional router support power',0,1000,1,'kW']]],
 ['Cooling & five-year costs',[
 ['cooling','Cooling method',{air:'Air + chillers',evaporative:'Air + evaporative',liquid:'Direct liquid',immersion:'Immersion'}],['climate','Site climate',{cold:'Cold',desert:'Desert'}],['coolant','Coolant supply temperature',10,50,1,'°C'],['resistance','Chip-to-coolant thermal resistance',0.001,0.02,0.001,'K/W'],['tempLimit','Assumed chip temperature limit',50,120,1,'°C'],['util','Average GPU power utilization',10,100,5,'%'],['electricity','Electricity price',0.02,0.30,0.0001,'$/kWh'],['building','Buildings / installed kW',0,30,0.1,'$k'],['network','Networking / GPU purchase cost',0,30,1,'%'],['maintenance','Annual maintenance / installed capital',0,10,0.5,'%'],['prefill','Prefill + memory power allowance',0,100,5,'%'],['otherMw','Extra CPU / storage support (what-if)',0,50,1,'MW'],['coolingCapex','Cooling installation cost',0,20000,100,'$/kW']]]
];
function controls(){ $('controls').innerHTML=groups.map(([title,fields],idx)=>`<details id="${idx===0?'routing-controls':title==='Optional scientific tool QPUs'?'scientific-controls':'control-group-'+idx}" ${idx===0?'open':''}><summary>${title}</summary>${fields.map(([id,label,min,max,step,unit])=> typeof min==='object'?`<label class="control">${label}<select id="c-${id}">${Object.entries(min).map(([v,n])=>`<option value="${v}" ${String(p[id])===v?'selected':''}>${n}</option>`).join('')}</select></label>`:`<label class="control" for="c-${id}"><span>${label}</span><span class="number"><input id="c-${id}" type="number" min="${min}" max="${max}" step="${step}" value="${p[id]??''}" placeholder="Unknown"><small>${unit}</small></span><small class="input-evidence">${EVIDENCE[id]?.short??'Editable scenario assumption'}</small></label>`).join('')}</details>`).join('');
}
const fieldById=new Map(groups.flatMap(g=>g[1]).map(f=>[f[0],f]));
function onControl(e){
 const id=e.target.id?.replace(/^c-/,''),field=fieldById.get(id);if(!field)return;
 const [,,min,max,step]=field;
 if(typeof min==='object'){
  if(e.type!=='change')return;
  if(['caseId','preset','rolloutStrategy'].includes(id)){
   const caseId=id==='caseId'?e.target.value:p.caseId,preset=id==='preset'?e.target.value:p.preset;
   const strategy=id==='rolloutStrategy'?e.target.value:p.rolloutStrategy;
   p=buildCaseScenario(caseId,preset,strategy);profileCustomized=false;year=2030;$('year').value=year;
   p.policyEvidence=null;controls();loadCaseComparison();render();return;
  }
  p[id]=['qcRouterOn','specDecode'].includes(id)?e.target.value==='true':e.target.value;
 }else{
  const raw=e.target.value.trim(),n=Number(raw);
  p[id]=raw===''||!Number.isFinite(n)?null:n;
  if(e.type==='change'&&Number.isFinite(p[id])){p[id]=Math.min(max,Math.max(min,step===1?Math.round(p[id]):p[id]));e.target.value=p[id];}
 }
 profileCustomized=true;render();
}
$('controls').addEventListener('input',onControl);
$('controls').addEventListener('change',onControl);

function renderInputHealth(missing){
 $('computed-output').hidden=missing.length>0;
 $('export').disabled=missing.length>0;$('play').disabled=missing.length>0;
 if(missing.length&&timer){clearInterval(timer);timer=null;$('play').textContent='▶ Play rollout';}
 $('missing-badge').hidden=missing.length===0;
 $('missing-badge').textContent=`⚠ ${missing.length} required input${missing.length===1?'':'s'} missing · graphs paused`;
 $('input-error').hidden=missing.length===0;
 for(const [id] of fieldById){const el=$(`c-${id}`);if(el)el.setAttribute('aria-invalid',String(missing.includes(id)));}
 $('input-error').innerHTML=missing.length?`<strong><span aria-hidden="true">⚠</span> Graph unavailable: required information is missing</strong><p>The graph and calculated results are hidden because these inputs were deleted or are not supplied. They are not treated as zero.</p><ul>${missing.map(id=>`<li><button class="missing-input" data-field="${id}">${fieldById.get(id)?.[1]??id}</button></li>`).join('')}</ul><p>Enter the missing values or load a scenario to restore a complete set of active inputs. Enabling the scientific pool also requires its job throughput, equivalent GPU work and price.</p>`:'';
 const scenario=SCENARIOS[p.preset];
 $('scenario-summary').innerHTML=`<strong>Case ${p.caseId} · ${CASES[p.caseId].name} · ${population(CASES[p.caseId].users)} users</strong><p>${scenario.description} ${profileCustomized?'Edited inputs.':p.rolloutStrategy==='bestCost'?'Lowest modeled five-year cost among four starting-fleet candidates. All required QPUs may be installed in 2030; choose Annual deployment for an explicit yearly adoption schedule.':`Annual deployment: assignment adoption rises from ${p.qcAdoptionStart}% in ${p.qcRouterStart} to 100% in ${p.qcAdoptionEndYear}; installed hardware must also have capacity.`} Initial routing QPUs: ${p.qcRouterInitial??'missing'}; maximum: ${p.qcRouterMax??'missing'}; speculative decoding: ${p.specDecode?'on (2 accepted tokens assumed)':'off'}; extra QC throughput: ${p.qcRouterGain??'missing'}%.</p><p>${missing.length?'⚠ Required inputs missing.':'✓ All active numerical inputs supplied.'} Filled thermal and timing values are scenario assumptions, not measured hardware guarantees. Preset selection reloads the complete case-specific profile.</p>`;
}
$('missing-badge').addEventListener('click',()=>$('input-error').scrollIntoView({block:'center',behavior:'smooth'}));
$('input-error').addEventListener('click',e=>{const target=e.target.closest('[data-field]');if(!target)return;const input=$(`c-${target.dataset.field}`);if(!input)return;input.closest('details').open=true;input.focus();input.scrollIntoView({block:'center',behavior:'smooth'});});
function chart(rows){const w=850,h=240,pad=42,max=Math.max(550,...rows.flatMap(r=>[r.unoptimizedMw,r.optimizedMw,r.hybridMw]))*1.1,x=i=>pad+i*(w-2*pad)/(rows.length-1),y=v=>h-pad-v/max*(h-2*pad),line=k=>rows.map((r,i)=>`${x(i)},${y(r[k])}`).join(' ');return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="GPU fleet before routing, classical optimized fleet, and QC-routed design peak grid demand"><line x1="${pad}" x2="${w-pad}" y1="${y(500)}" y2="${y(500)}" stroke="#f07575" stroke-dasharray="5 5"/><text x="${pad}" y="${y(500)-7}" fill="#f07575">500 MW limit</text>${[0,max/2,max].map(v=>`<text x="2" y="${y(v)}" fill="#8691aa">${Math.round(v)}</text>`).join('')}<polyline points="${line('unoptimizedMw')}" fill="none" stroke="#8b92ad" stroke-width="3"/>${showClassical?`<polyline points="${line('optimizedMw')}" fill="none" stroke="#c026d3" stroke-width="2"/>`: ""}<polyline points="${line('hybridMw')}" fill="none" stroke="#22d3ee" stroke-width="3" stroke-dasharray="${rows.every(r=>r.powerComplete)?'none':'7 4'}"/>${rows.map((r,i)=>`<line x1="${x(i)}" x2="${x(i)}" y1="${pad}" y2="${h-pad}" stroke="${r.year===year?'#c026d3':'transparent'}"/><circle cx="${x(i)}" cy="${y(r.hybridMw)}" r="6" fill="#22d3ee" data-year="${r.year}" tabindex="0" role="button" aria-label="Inspect ${r.year}"><title>${r.year}: hybrid ${fmt(r.hybridMw)} MW; baseline ${fmt(r.baseMw)} MW</title></circle><text x="${x(i)}" y="${h-12}" fill="#8691aa" text-anchor="middle">${r.year}</text>`).join('')}</svg>`;}
function runningChart(rows){
 const w=850,h=230,pad=45,max=Math.max(1,...rows.flatMap(r=>[r.baseRunning,r.hybridRunning]))/1e6*1.15;
 const x=i=>pad+i*(w-2*pad)/(rows.length-1),y=v=>h-pad-(v/1e6)/max*(h-2*pad);
 const line=key=>rows.map((r,i)=>`${x(i)},${y(r[key])}`).join(' ');
 return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Annual running costs for GPU-only and QC-hybrid from 2030 through 2040"><text x="3" y="18" fill="#8691aa">$M / year</text>${[0,max/2,max].map(v=>`<text x="3" y="${y(v*1e6)}" fill="#8691aa">${Math.round(v)}</text>`).join('')}<polyline points="${line('baseRunning')}" fill="none" stroke="#8b92ad" stroke-width="3"/><polyline points="${line('hybridRunning')}" fill="none" stroke="#22d3ee" stroke-width="3"/>${rows.map((r,i)=>`<circle cx="${x(i)}" cy="${y(r.hybridRunning)}" r="5" fill="#22d3ee"><title>${r.year}: ${money(r.hybridRunning)} hybrid running cost</title></circle><text x="${x(i)}" y="${h-12}" fill="#8691aa" text-anchor="middle">${r.year}</text>`).join('')}</svg>`;
}
function render(){
 const missing=missingInputs(p);renderInputHealth(missing);if(missing.length)return;
 const result=simulate(p),r=result.rows[year-2030],c=CASES[p.caseId];
 const unknown='Not specified';const amount=(n,complete)=>complete?money(n):`${money(n)} known + unspecified`;
 $('yearLabel').textContent=year;
 document.body.classList.toggle('has-tool-qpus',p.add>0||r.qCount>0);
 $('progress').textContent=`${year} · ${r.qcRouterCount} routing QPUs installed (${r.qcRouterNew} new this year)${r.qCount>0?` · ${r.qCount} scientific tool QPUs installed (${r.newQ} new)`:''}`;
 $('case-heading').textContent=`Case ${p.caseId} · ${population(c.users)} ${c.name.toLowerCase()}`;
 $('design-heading').textContent=`Research-note comparison · case ${p.caseId}`;
 const checks=[['Known grid load',r.hybridMw<=500,`${r.powerComplete?'':'≥ '}${fmt(r.hybridMw)} / 500 MW${r.powerComplete?'':' · QC power unspecified'}`],['Five-year budget',result.budgetComplete&&result.budgetOk,result.budgetComplete?`${money(result.windowCost)} / $30B`:`${money(result.windowCost)} known subtotal · full budget not determined`],['Thermal envelope',r.thermalKnown&&r.thermalOk,r.thermalKnown?`${fmt(r.temperature)} / ${p.tempLimit} °C`:'Limit / resistance unspecified'],['Workload capacity covered',r.served>=.999999,`${fmt(r.served*100)}% of the same case workload · modeled screen`],['QC assignment time',r.schedulingOk,r.schedulerKnown?(p.qcRouterOn?`${p.qcRouterLatencyMs} ms (assumed)`:'Classical reference'):'Not specified in research notes']];
 $('verdict').innerHTML=`<div class="verdict ${result.feasible?'pass':'fail'}"><strong>${result.feasible?'Passes entered scenario checks · not a hardware certification':'Scenario comparison · full service not established'}</strong><span>Research-note values are decode/rack estimates. Cost proxies and throughput assumptions are included; prefill, calibrated thermal limits and validated assignment timing remain outside the completed model.</span></div><div class="checks">${checks.map(([label,ok,note])=>`<div class="${ok?'good':'bad'}"><b>${ok?'✓':'?'} ${label}</b><small>${note}</small></div>`).join('')}</div>`;
 $('metrics').innerHTML=[['Modeled cumulative cost difference',r.costsComplete?money(r.savings):'Not determined','Includes purchases paid and running costs · scenario estimate'],['Known grid difference',`${fmt(r.baseMw-r.hybridMw)} MW`,r.powerComplete?'All supplied system power included':'QC router power is not supplied; benefit is not fully established'],['Annual energy difference',r.energyKnown?`${fmt(r.baseGwh-r.hybridGwh)} GWh`:'Not determined','Needs average load and full QC system power'],['Modeled cost break-even',result.breakEven??'Not determined',result.budgetComplete?'Calculated through 2040':'Needs the missing purchase and operating costs']].map(([label,value,note])=>`<div class="metric"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('');
 $('chart').innerHTML=chart(result.rows);$('running-chart').innerHTML=runningChart(result.rows);
 renderRollout(r,result);renderWorkload(r);renderBenefit(r,result);renderQuantumRoles(r);
 $('gpu-year-heading').textContent=`GPU and quantum systems installed in ${year}`;
 $('hybrid-legend').textContent=p.qcRouterOn?'QC-hybrid design':'Classical source-policy design';
 $('routerBadge').textContent=p.qcRouterOn?'QC ASSIGNMENT ROUTER · PROPOSED':'CLASSICAL ROUTING REFERENCE';
 $('flow').innerHTML=`<div><small>Case ${p.caseId}</small><strong>${population(c.users)} users</strong><span>${c.name}</span></div><b>→</b><div><small>Assignment router</small><strong>${r.qcRouterCount} routing QPUs</strong><span>${fmt(r.routingCoverage*100)}% assignment coverage · assumed</span></div><b>→</b><div><small>GPU fleet</small><strong>${fmt(r.hybridRacks*144,0)} GPU equivalents</strong><span>${fmt(r.hybridRacks,1)} rack equivalents</span></div>${r.qCount>0?`<b>↔</b><div><small>Additional scientific tool processors</small><strong>${r.qCount} tool QPUs</strong><span>Separate from routing QPUs</span></div>`:''}`;
 const names=['N. Virginia','Midwest','West Texas','Nordics','Iceland','Gulf'];
 $('sites').innerHTML=names.map((name,i)=>`<div class="site"><span>${name}</span><div class="rackmap">${Array.from({length:12},(_,j)=>`<i class="${r.thermalKnown?(r.thermalOk?'cool':'hot'):'unmeasured'}" style="opacity:${.5+((i+j)%4)*.12}"></i>`).join('')}</div><strong>${r.powerComplete?'':'≥ '}${fmt(r.hybridMw/6)} MW</strong><small>${r.thermalKnown?`${fmt(r.temperature)} °C estimate`:'Temperature not calibrated'} · ${Math.floor(r.hybridPhysicalRacks/6)+(i<r.hybridPhysicalRacks%6?1:0)} physical GPU racks</small></div>`).join('');
 $('costs').innerHTML=Object.entries(r.costs).map(([key,v])=>{const missing={quantum:r.qCount>0&&!Number.isFinite(p.qPrice),infrastructure:![p.building,p.network,p.coolingCapex].every(Number.isFinite),electricity:!r.operatingComplete,maintenance:!Number.isFinite(p.maintenance),qc_router:r.qcRouterCount>0&&!Number.isFinite(p.qcRouterPrice)}[key];return `<div class="cost"><span>${key.replaceAll('_',' ')}</span><b>${missing?'Not determined':money(v)}</b></div>`;}).join('')+`<p class="muted">Known subtotal ${money(r.hybridSpend)}. ${r.costsComplete?'All entered costs included.':'Full annual spending is not determined. Missing inputs are excluded from this subtotal, not assumed free.'}</p>`;
 $('advancement').innerHTML=`<div class="cost"><span>Routing QPUs installed in ${year}</span><b>${r.qcRouterCount}</b></div><div class="cost"><span>Routing QPUs added in ${year}</span><b>${r.qcRouterNew}</b></div><div class="cost"><span>Total quantum systems installed</span><b>${r.totalQuantumCount}</b></div>${r.qCount>0?`<div class="cost"><span>Scientific tool QPUs installed (separate)</span><b>${r.qCount}</b></div><div class="cost"><span>Scientific tool-QPU wall power</span><b>${fmt(r.qPower)} MW</b></div>`:''}<p>${SCENARIOS[p.preset].description} Scientific hardware trends remain separate inputs.</p>`;
 $('rows').innerHTML=result.rows.map(a=>`<tr class="${a.year===year?'selected':''}"><th><button class="year-jump" data-year="${a.year}">${a.year}</button></th><td>${fmt(a.baseRacks,1)} / ${fmt(a.hybridRacks,1)}</td><td>${a.qcRouterNew} / ${a.qcRouterCount}<br>${fmt(a.routingCoverage*100)}% covered</td><td class="tool-qpu-column">${a.newQ} / ${a.qCount}</td><td>${fmt(a.baseMw)} / ${a.powerComplete?'':'≥ '}${fmt(a.hybridMw)}</td><td>${a.energyKnown?fmt(a.hybridGwh):'Not determined'}</td><td>${money(a.hybridInitial)} known upfront<br>${a.operatingComplete?money(a.hybridRunning)+' running':'Running costs unspecified'}</td><td>${a.costsComplete?money(a.savings):'Not determined'}</td><td>${fmt(a.served*100)}%</td></tr>`).join('');
 $('profile-provenance').textContent=p.engineProfile?`Imported ${p.engineProfile.label}. Additional model assumptions from dc_sim, separate from the research-note reference.`:'';
 $('scope').textContent=`Source: ${SOURCE.source}. Hardware is the fixed 2035 catalog; the 2030–2040 axis is a rollout scenario using those same inputs, not new annual measurements. Research-note defaults contain no annual improvements. The $30B budget covers 2030–2034; total cost cannot be certified while inputs remain unspecified.`;
 renderDesignComparison(r);renderExplanation(r,result);renderSpending(r,result);
}
function renderDesignComparison(r){
 const c=CASES[p.caseId];
 $('research-reference').innerHTML=`<div class="table-wrap"><table class="data"><thead><tr><th>Base use case</th><th>Population</th><th>Baseline: MW / rack cost</th><th>Brief levers: MW / rack cost</th><th>+ speculative decoding</th></tr></thead><tbody>${Object.entries(CASES).map(([id,v])=>`<tr class="${id===p.caseId?'selected':''}"><th>${id} · ${v.name}</th><td>${population(v.users)}</td><td>${fmt(v.baseline.facilityMw,0)} MW / ${money(v.baseline.rackCapexUsd)}</td><td>${fmt(v.routed.facilityMw,0)} MW / ${money(v.routed.rackCapexUsd)}</td><td>${fmt(v.speculative.facilityMw,0)} MW / ${money(v.speculative.rackCapexUsd)}</td></tr>`).join('')}</tbody></table></div><p class="muted">Direct liquid, cold site, PUE 1.07. Values are generated from the existing fleet-card model; notes round them. C uses all three brief levers. A has no beneficial brief lever; routing chat alone worsens its power to about 1,029 MW. Speculative decoding remains an explicit source assumption.</p>`;
 $('design-comparison').innerHTML=`<div class="table-wrap"><table class="data"><thead><tr><th>Case ${p.caseId} design</th><th>GPU rack equivalents</th><th>Known grid load</th><th>Known rack capex</th><th>Total cost</th></tr></thead><tbody><tr><th>Baseline GPU fleet</th><td>${fmt(r.unoptimizedRacks,1)}</td><td>${fmt(r.unoptimizedMw)} MW</td><td>${money(r.unoptimizedRacks*SOURCE.gpuRack.usd)}</td><td>${r.costsComplete?money(r.unoptimizedCumulative):'Not fully specified'}</td></tr><tr class="classical-row"><th>Classical optimized reference</th><td>${fmt(r.optimizedRacks,1)}</td><td>${fmt(r.optimizedMw)} MW</td><td>${money(r.optimizedRacks*SOURCE.gpuRack.usd)}</td><td>Not fully specified</td></tr><tr><th>${p.qcRouterOn?'GPUs + routing QPUs':'GPU fleet with source policies'}</th><td>${fmt(r.hybridRacks,1)}</td><td>${r.powerComplete?'':'≥ '}${fmt(r.hybridMw)} MW${r.powerComplete?'':' + unknown QC power'}</td><td>${money(r.hybridRacks*SOURCE.gpuRack.usd)} in active GPU capacity + ${Number.isFinite(p.qcRouterPrice)?money(r.qcRouterCount*p.qcRouterPrice*1e6):'unknown QC purchase'}</td><td>${r.costsComplete?money(r.hybridCumulative):'Not determined'}</td></tr></tbody></table></div><p><strong>Full source-policy rack-capex opportunity at 100% coverage:</strong> ${money(r.policyRackSavings)}. It is not full-system savings and is not evidence of a quantum-specific routing advantage.</p><p>${p.caseId==='A'?'Case A is pure chat serving. The notes identify no established QPU acceleration for token generation.':p.caseId==='B'?'Case B has background-agent tool calls that could use suitable quantum methods. The notes do not supply a measured QC scheduling advantage.':'Case C mixes chat and agent work. Its source routing benefits do not establish quantum acceleration of ordinary LLM serving.'}</p>`;
}
function renderExplanation(r,result){
 const c=CASES[p.caseId],v=c[p.specDecode?'speculative':'routed'],t=year-2030,last=result.rows.at(-1);
 $('gpu-accounting').innerHTML=[['Baseline GPU racks',fmt(r.baseRacks,1),`${fmt(r.baseRacks*144,0)} GPU equivalents`],['Hybrid GPU racks',fmt(r.hybridRacks,1),`${r.qcRouterCount} routing QPUs${r.qCount>0?` + ${r.qCount} scientific tool QPUs`: ""}`],['GPU capacity removed / avoided',fmt(r.gpuRacksReleased*144,0),'Derived from source policies and any explicitly entered offloading assumptions'],[`Total quantum systems · ${year}`,String(r.totalQuantumCount),`${r.qcRouterCount} routing QPUs${r.qCount>0?` + ${r.qCount} scientific tool QPUs`: ""} installed in ${year}. Final 2040 fleet: ${last.totalQuantumCount} total quantum systems.`]].map(([label,value,note])=>`<div class="metric"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('');
 $('future-math').innerHTML=`<ol><li><strong>Reference:</strong> case ${p.caseId}, ${population(c.users)} users; ${fmt(c.baseline.facilityMw)} MW and ${money(c.baseline.rackCapexUsd)} in baseline racks. The source's ${p.specDecode?'speculative-decoding':'brief-lever'} option uses ${fmt(v.facilityMw)} MW and ${money(v.rackCapexUsd)} in racks.</li><li><strong>Future scaling:</strong> rack requirement = source racks × (1 + ${p.demandGrowth}% workload growth)^${t} ÷ (1 + ${p.gpuGrowth}% GPU throughput growth)^${t}. GPU technology stays fixed at zero throughput growth; QC rollout can still reduce the required GPU fleet as coverage expands.</li><li><strong>System counts:</strong> ${r.qcRouterCount} dedicated QC assignment router and ${r.qCount} additional tool QPUs. Counts always refer to the selected year. Click 2040 to see the final installed fleet.</li><li><strong>QC cost and power:</strong> ${Number.isFinite(p.qcRouterPrice)?money(p.qcRouterPrice*1e6)+' per router': 'purchase price not specified'}; ${Number.isFinite(p.qcRouterMw)?fmt(p.qcRouterMw,4)+' MW per router':'wall power not specified'}; ${Number.isFinite(p.qcRouterLatencyMs)?p.qcRouterLatencyMs+' ms assumed latency':'assignment performance not specified'}. The sourced proposal uses an annealer hardware proxy, not a validated data-center scheduler specification. See the evidence register.</li><li><strong>Spending:</strong> known upfront GPU capital is shown separately from optional QC/infrastructure costs and annual running costs. Missing costs are not zero, so a complete hybrid advantage or break-even date is not calculated until they are supplied.</li><li><strong>Moore and Neven:</strong> neither law is used to lower usage automatically. The notes' historical hardware trends can motivate a what-if, but do not predict a fixed percentage saving. Quantum power falls only when you explicitly enter a new-system power-reduction assumption.</li></ol>`;
}
function renderSpending(r,result){
 const max=Math.max(r.baseCapital,r.hybridCapital,1),bar=(value,color,denominator=max)=>`<div class="spend-track"><span style="width:${100*value/denominator}%;background:${color}"></span></div>`;
 $('spending-visual').innerHTML=`<div class="twocol"><div><h3>Purchases paid through ${year}</h3><div class="cost"><span>GPU-only · known capital</span><b>${money(r.baseCapital)}</b></div>${bar(r.baseCapital,'#8b92ad')}<div class="cost"><span>GPUs + QC router · known capital</span><b>${money(r.hybridCapital)}</b></div>${bar(r.hybridCapital,'#22d3ee')}<p class="muted">${r.initialComplete?'All entered capital components included.':'GPU rack costs are available. QC purchase, buildings, cooling plant and network installation remain unspecified unless entered.'}</p></div><div><h3>Annual running costs · ${year}</h3>${r.operatingComplete?`<div class="cost"><span>GPU-only</span><b>${money(r.baseRunning)}</b></div>${bar(r.baseRunning,'#8b92ad',Math.max(r.baseRunning,r.hybridRunning,1))}<div class="cost"><span>GPUs + QC router</span><b>${money(r.hybridRunning)}</b></div>${bar(r.hybridRunning,'#22d3ee',Math.max(r.baseRunning,r.hybridRunning,1))}`:'<div class="unknown-cost">Not specified in research notes<br><small>Enter electricity price, average load, maintenance and QC system power to estimate both running costs.</small></div>'}<p class="muted">Annual running costs can decrease as deployment expands. Cumulative spending still increases because it adds all spending so far. The GPU-only and hybrid estimates use the same entered electricity and load assumptions. QC and tool-QPU wall power are counted separately.</p></div></div><div class="table-wrap"><table class="data"><thead><tr><th>Comparison through ${year}</th><th>Upfront purchases</th><th>Running costs accumulated</th><th>Total</th></tr></thead><tbody><tr><th>GPU-only</th><td>${money(r.baseCapital)} known</td><td>${r.operatingComplete?money(r.baseOperating):'Not determined'}</td><td>${r.costsComplete?money(r.baseCumulative):'Not determined'}</td></tr><tr><th>${p.qcRouterOn?'GPUs + routing QPUs':'GPU fleet with source policies'}</th><td>${money(r.hybridCapital)} known${r.initialComplete?'':' + unspecified'}</td><td>${r.operatingComplete?money(r.hybridOperating):'Not determined'}</td><td>${r.costsComplete?money(r.hybridCumulative):'Not determined'}</td></tr></tbody></table></div><p class="muted">The $30B limit includes more than rack purchases. ${result.budgetComplete?'The supplied inputs support a modeled full-cost check.':'This reference view does not assert a full-budget pass.'}</p>`;
}
