function renderBenefit(r,result){
 const costBenefit=r.costsComplete&&r.savings>0,powerBenefit=r.powerComplete&&r.hybridMw<r.unoptimizedMw;
 $('hybrid-benefit').innerHTML=`<p class="eyebrow">GPU-ONLY VS QC-HYBRID · ${year}</p><h2>${costBenefit&&powerBenefit?'The hybrid opportunity: less power, lower modeled cost':'Compare the hybrid against the same GPU-only workload'}</h2><div class="metrics"><div class="metric"><span>Grid power reduced</span><strong>${r.powerComplete?fmt((r.unoptimizedMw-r.hybridMw)/r.unoptimizedMw*100)+'%':'Not determined'}</strong><small>${fmt(r.unoptimizedMw)} → ${fmt(r.hybridMw)} MW${r.powerComplete?'':' + unknown system load'}</small></div><div class="metric"><span>Cumulative spending avoided</span><strong>${r.costsComplete?money(r.unoptimizedCumulative-r.hybridCumulative):'Not determined'}</strong><small>Purchases and running costs through ${year}; no GPU retirement refund</small></div><div class="metric"><span>Modeled workload covered</span><strong>${fmt(r.served*100)}%</strong><small>Same case population and work · capacity screen, not certified deadlines</small></div><div class="metric"><span>Five-year hybrid spending</span><strong>${result.budgetComplete?money(result.windowCost):'Not determined'}</strong><small>${result.budgetComplete&&result.budgetOk?'Within the $30B modeled budget':'Complete inputs and $30B budget check required'} · 2030–2034</small></div></div><p>The optimistic proposal connects QC routing coverage to the source-policy opportunity and adds ${p.qcRouterGain}% assumed extra throughput on covered work. Costs include every installed QC router. All active inputs are supplied; thermal, timing and QC-throughput values include explicit assumptions. This is a scenario, not measured quantum advantage. ${r.unoptimizedMw>500?'The GPU-only comparator exceeds the 500 MW cap; its spending is the cost of provisioning the requested workload, not a feasible deployment.':''}</p>`;
}
function renderWorkload(r){
 const c=CASES[p.caseId];
 $('workload').innerHTML=`<h2>Same workload, accounted for · ${year}</h2><p>Target: all ${population(c.users)} ${c.name.toLowerCase()} at the source quality and deadline requirements. Hardware counts are not percentages of users served.</p><div class="workload-bar" role="img" aria-label="GPU work ${fmt(r.gpuWorkFraction*100)}%, quantum tool work ${fmt(r.quantumToolWorkFraction*100)}%, unserved ${fmt(r.unservedFraction*100)}%"><span style="width:${r.gpuWorkFraction*100}%;background:#22d3ee"></span><span style="width:${r.quantumToolWorkFraction*100}%;background:#c026d3"></span><span style="width:${r.unservedFraction*100}%;background:#f07575"></span></div><div class="metrics"><div class="metric"><span>Work executed by GPUs</span><strong>${fmt(r.gpuWorkFraction*100)}%</strong></div><div class="metric"><span>Scientific work executed by QPUs</span><strong>${fmt(r.quantumToolWorkFraction*100)}%</strong></div><div class="metric"><span>Work unserved in capacity screen</span><strong>${fmt(r.unservedFraction*100)}%</strong></div><div class="metric"><span>Total workload capacity covered</span><strong>${fmt(r.served*100)}%</strong></div></div><p><strong>Execution sums to 100%:</strong> GPU work + quantum tool work + unserved work = 100% of the same baseline workload, expressed in GPU-work equivalents. QC routers plan ${fmt(r.routingCoverage*100)}% of assignments; those decisions are not counted a second time as completed work.</p><p class="muted">Fewer GPU racks can cover the same modeled work because source policies reduce the required GPU work and the extra QC throughput is an explicit assumption. This is not measured server utilization or proof of end-to-end service. Missing QC power makes grid service an upper bound; prefill, memory, deadlines and accepted output quality still need validation.</p>`;
}
function renderRollout(r,result){
 const last=result.rows.at(-1),gross=r.routingGrossMwAvoided,net=gross-r.routerFacilityMw;
 $('qc-rollout').innerHTML=`<p class="eyebrow">QC ASSIGNMENT ROUTER · ${year} · SCENARIO</p><h2>Add routing capacity, then account for the benefit</h2><div class="metrics"><div class="metric"><span>Routing QPUs installed · ${year}</span><strong>${r.qcRouterCount}</strong><small>${r.qcRouterNew} new this year · ${last.qcRouterCount} installed by 2040</small></div><div class="metric"><span>Assignment workload covered</span><strong>${fmt(r.routingCoverage*100)}%</strong><small>Hardware capacity: ${fmt(r.hardwareCoverage*100)}%; scheduled deployment: ${fmt(r.plannedCoverage*100)}% · assumptions</small></div><div class="metric"><span>GPU rack equivalents avoided</span><strong>${fmt(r.qcGpuRacksAvoided)}</strong><small>${fmt(r.policyRacksAvoided)} from source-policy opportunity + ${fmt(r.qcExtraRacksAvoided)} from assumed extra throughput</small></div><div class="metric"><span>Net router power benefit</span><strong>${r.routerNetMwKnown?fmt(net)+' MW':'Not determined'}</strong><small>${fmt(gross)} MW GPU load avoided − ${r.routerNetMwKnown?fmt(r.routerFacilityMw,4)+' MW router load':'unknown router load'}. Tool QPUs are separate.</small></div></div><div class="coverage-bar" aria-label="${fmt(r.routingCoverage*100)} percent of assignments covered"><span style="width:${r.routingCoverage*100}%"></span></div><p><strong>Why the GPU line changes:</strong> deployment adopts more assignments each year, limited by installed routing hardware. The schedule starts at ${p.qcAdoptionStart}% in ${p.qcRouterStart} and reaches 100% in ${p.qcAdoptionEndYear}. Covered work receives a proportional share of the existing source-policy improvement, then an explicitly assumed ${p.qcRouterGain}% extra throughput on that covered share. Extra benefit stops at 100% coverage; buying more routers still costs money and power.</p><p class="muted">These equations model the proposed QC architecture; they do not execute a quantum algorithm. The source policies are also achievable classically. ${r.hybridMw>500?'This year exceeds the 500 MW cap; the rollout cannot claim full service under the stated restrictions.':''} ${r.qCount>0&&r.offload===0?'Warning: installed scientific tool QPUs currently offload no work and only add overhead.':''}</p><div class="table-wrap"><table class="data"><thead><tr><th>Year</th><th>QC new / installed</th><th>Coverage</th><th>GPU MW avoided</th><th>Router MW added</th><th>Net MW avoided</th></tr></thead><tbody>${result.rows.map(a=>`<tr class="${a.year===year?'selected':''}"><th>${a.year}</th><td>${a.qcRouterNew} / ${a.qcRouterCount}</td><td>${fmt(a.routingCoverage*100)}%</td><td>${fmt(a.routingGrossMwAvoided)}</td><td>${a.routerNetMwKnown?fmt(a.routerFacilityMw,4):'Unknown'}</td><td>${a.routerNetMwKnown?fmt(a.routingGrossMwAvoided-a.routerFacilityMw):'Unknown'}</td></tr>`).join('')}</tbody></table></div>`;
}
