const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function request(url,body){const response=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});if(!response.ok)throw new Error(`Engine request failed (${response.status})`);const data=await response.json();if(data.error)throw new Error(data.error);return data;}
function showEngine(){const rows=engineData.rows, fifo=rows.find(r=>r.policy==='fifo');
 $('engine-results').innerHTML=`<p>Preset <strong>${escapeHtml(engineData.preset)}</strong> · seed ${engineData.seed} · ${fmt(engineData.horizon_s/3600)} simulated hours. Daily costs extrapolate this window.</p><div class="table-wrap"><table class="data"><thead><tr><th>Policy</th><th>Full-service score</th><th>Tasks on time</th><th>Peak MW</th><th>Energy MWh</th><th>Total $/day</th><th>Difference vs FIFO/day</th><th>Difference vs GPU reference/day</th></tr></thead><tbody>${rows.map(r=>`<tr><th>${escapeHtml(r.policy)}</th><td class="${r.served>=99.999?'good':'bad'}">${fmt(r.served)}%</td><td>${r.tasks_ok}/${r.tasks_n}</td><td>${fmt(r.peak_mw)}</td><td>${fmt(r.energy_mwh)}</td><td>${money(r.usd_day_m*1e6)}</td><td>${r.policy==='ref_gpu_only_fleet'?'Different fleet':money((fifo.usd_day_m-r.usd_day_m)*1e6)}</td><td>${money(r.saved_vs_ref_total_usd_day)}</td></tr>`).join('')}</tbody></table></div><p class="muted">Same-fleet FIFO comparison isolates the assignment policy. GPU-only reference includes different hardware purchases. Neither is a valid full-service savings claim when service is below 100%. These outputs come from the engine, not from real hardware measurements.</p>`;
 $('engine-apply').disabled=false;
}
const CASE_PRESETS={A:'case_A_prompters',B:'case_B_agents',C:'case_C_knowledge'};
async function loadCaseComparison(){
 if(!engineMeta)return;
 const seq=++comparisonSequence;
 $('engine-apply').disabled=true;engineData=null;
 $('engine-results').textContent='Loading saved reference assignments…';
 const preset=CASE_PRESETS[p.caseId];
 $('engine-preset').innerHTML=`<option value="${preset}">${p.caseId} · ${CASES[p.caseId].name}</option>`;
 $('router-full').href=replayUrl();
 $('router-frame').removeAttribute('src');
 if($('live-router').open)$('router-frame').src=replayUrl();
 try{
  const data=liveEngine?await request('/api/thermal/compare',{preset,seed:Number($('engine-seed').value)}):await request(`./snapshots/comparison-${p.caseId}.json`);
  if(seq!==comparisonSequence)return;
  engineData=data;showEngine();
  $('snapshot-note').textContent=`Saved ${p.caseId} case, ${population(CASES[p.caseId].users)} users. Same existing dc_sim assumptions, not new measurements. Its fleet and cost assumptions differ from the research-note fleet card; the two sets of totals must not be treated as the same design.`;
 }catch(e){if(seq===comparisonSequence)$('engine-results').textContent=e.message;}
}
